    const AGENT_SESSION_PREFIX = 'dsh-wiki-agent-session:'
    const API = '/wiki-manager/api'
    const KB_CACHE_TTL = 3000
    const kbTriggerCache = { at: 0, items: [] }
    const invalidateKbTriggerCache = () => { kbTriggerCache.at = 0 }
    const KB_REF_PREFIX = 'kb:'

    const encodeKbRef = (kb) => KB_REF_PREFIX + encodeURIComponent(JSON.stringify({
      id: kb.id,
      name: kb.name,
      path: kb.path,
      url: kb.url ?? '',
    }))

    const decodeKbRef = (ref) => {
      if (typeof ref !== 'string' || !ref.startsWith(KB_REF_PREFIX)) return null
      try {
        const kb = JSON.parse(decodeURIComponent(ref.slice(KB_REF_PREFIX.length)))
        return kb !== null && typeof kb === 'object' && typeof kb.path === 'string' ? kb : null
      } catch {
        return null
      }
    }

    async function loadKnowledgeBases(signal) {
      if (kbTriggerCache.at !== 0 && Date.now() - kbTriggerCache.at < KB_CACHE_TTL) return kbTriggerCache.items
      const response = await fetch(`${API}/kbs`, { signal })
      if (!response.ok) throw new Error(`请求失败（HTTP ${response.status}）`)
      const payload = await response.json()
      const items = Array.isArray(payload?.items) ? payload.items : []
      kbTriggerCache.at = Date.now()
      kbTriggerCache.items = items
      return items
    }

