    // Muted, Obsidian-like palette: notes stay quiet, tag layer is the only
    // saturated colour, domain hue remains distinguishable in the legend.
    const DOMAIN_COLORS = {
      AGT: '#7E9DBA',
      RPT: '#6FAFBA',
      ONT: '#9B8EC4',
      PLT: '#C8A17E',
      RAG: '#7FB399',
      MIXED: '#9AA3AD',
      tag: '#5FC98A',
    }
    // Pages all share one muted hue; only the tag layer keeps its accent colour.
    const PAGE_COLOR = DOMAIN_COLORS.AGT
    const MAX_RENDER_NODES = 900
    const TARGET_ITERATIONS = 420
    const MAX_ZOOM = 20
    const CJK = /[\u3400-\u9fff]/u

    async function api(path, options = {}) {
      const init = { method: options.method ?? 'GET', headers: {} }
      if (options.body !== undefined) {
        init.headers['content-type'] = 'application/json'
        init.body = JSON.stringify(options.body)
      }
      const response = await fetch(`${API}${path}`, init)
      if (init.method !== 'GET' && path.startsWith('/kbs')) invalidateKbTriggerCache()
      let payload
      try {
        payload = await response.json()
      } catch {
        payload = undefined
      }
      if (!response.ok) throw new Error(payload?.error ?? `请求失败（HTTP ${response.status}）`)
      return payload
    }

    // ---------------------------------------------------------------------
    // Minimal, escaped Markdown rendering (no raw HTML from the vault)
    // ---------------------------------------------------------------------

    function escapeHtml(text) {
      return String(text)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
    }

    // A vault-relative path (e.g. `raw/articles/Foo.md`) only becomes a link
    // when the current graph really contains that page, so a plain mention of
    // a missing file never turns into a dead link.
    function vaultRef(raw, vaultPaths) {
      if (vaultPaths === undefined || vaultPaths === null) return null
      let value = String(raw ?? '').trim()
      if (value === '') return null
      if (/^[a-z][a-z0-9+.-]*:\/\//iu.test(value)) return null
      value = value.replace(/[?#].*$/u, '').replace(/^<|>$/gu, '').replace(/^\.?\//u, '')
      if (!/[./]/u.test(value)) return null
      const key = value.toLowerCase()
      const candidates = [[key, value]]
      if (key.startsWith('wiki/')) candidates.push([key.slice(5), value.slice(5)])
      else candidates.push([`wiki/${key}`, `wiki/${value}`])
      for (const [candidate, rel] of candidates) {
        if (vaultPaths.has(candidate)) return rel
      }
      return null
    }

    const vaultPathRe =
      /(?:wiki|raw|templates|prompts|schema|locale)\/[A-Za-z0-9_\-./%\u4e00-\u9fff]+\.(?:md|markdown)/gu

    function vaultLinkHtml(rel, label) {
      const target = String(rel).replaceAll('"', '&quot;')
      return `<span class="wm-wikilink wm-vaultLink" data-wikilink="${target}" role="link" tabindex="0">${label}</span>`
    }

    function linkifyVaultText(text, vaultPaths) {
      if (vaultPaths === undefined || vaultPaths === null) return text
      // Rewrite text nodes only, never tag names or attributes.
      return text.replace(/<[^>]*>|[^<]+/gu, (segment) => {
        if (segment.startsWith('<')) return segment
        return segment.replace(vaultPathRe, (match) => {
          const rel = vaultRef(match, vaultPaths)
          return rel === null ? match : vaultLinkHtml(rel, match)
        })
      })
    }

    function inlineMarkdown(text, vaultPaths) {
      let out = escapeHtml(text)
      out = out.replace(/`([^`]+)`/gu, (match, body) => {
        const rel = vaultRef(body, vaultPaths)
        return rel === null ? `<code>${body}</code>` : vaultLinkHtml(rel, body)
      })
      out = out.replace(/\*\*([^*]+)\*\*/gu, '<strong>$1</strong>')
      out = out.replace(/(^|[^*])\*([^*\n]+)\*/gu, '$1<em>$2</em>')
      out = out.replace(/\[\[([^\]|]*\|)?([^\]]*)\]\]/gu, (match, alias, label) => {
        const target = (alias === undefined ? label : alias.slice(0, -1)).trim()
        return `<span class="wm-wikilink" data-wikilink="${target}" role="link" tabindex="0">${label}</span>`
      })
      out = out.replace(/!\[([^\]]*)\]\([^)]*\)/gu, '<span class="wm-img">［图片：$1］</span>')
      out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/gu, (match, label, href) => {
        const rel = vaultRef(href, vaultPaths)
        return rel === null ? `<span class="wm-link">${label}</span>` : vaultLinkHtml(rel, label)
      })
      return linkifyVaultText(out, vaultPaths)
    }

    function renderMarkdown(markdown, vaultPaths) {
      const body = String(markdown ?? '').replace(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/u, '')
      const lines = body.split(/\r?\n/u)
      const html = []
      let list = null
      let code = null
      const closeList = () => {
        if (list !== null) {
          html.push(`</${list}>`)
          list = null
        }
      }
      for (let index = 0; index < lines.length; index += 1) {
        const line = lines[index]
        const fence = /^```/u.exec(line)
        if (fence !== null) {
          if (code === null) {
            closeList()
            code = []
          } else {
            html.push(`<pre class="wm-pre"><code>${escapeHtml(code.join('\n'))}</code></pre>`)
            code = null
          }
          continue
        }
        if (code !== null) {
          code.push(line)
          continue
        }
        if (line.trim() === '') {
          closeList()
          continue
        }
        const heading = /^(#{1,6})\s+(.*)$/u.exec(line)
        if (heading !== null) {
          closeList()
          const level = Math.min(heading[1].length + 2, 6)
          html.push(`<h${level}>${inlineMarkdown(heading[2], vaultPaths)}</h${level}>`)
          continue
        }
        if (/^(-{3,}|\*{3,})$/u.test(line.trim())) {
          closeList()
          html.push('<hr/>')
          continue
        }
        const quote = /^>\s?(.*)$/u.exec(line)
        if (quote !== null) {
          closeList()
          html.push(`<blockquote>${inlineMarkdown(quote[1], vaultPaths)}</blockquote>`)
          continue
        }
        const bullet = /^\s*[-*+]\s+(.*)$/u.exec(line)
        if (bullet !== null) {
          if (list !== 'ul') {
            closeList()
            html.push('<ul>')
            list = 'ul'
          }
          html.push(`<li>${inlineMarkdown(bullet[1], vaultPaths)}</li>`)
          continue
        }
        const ordered = /^\s*\d+[.)]\s+(.*)$/u.exec(line)
        if (ordered !== null) {
          if (list !== 'ol') {
            closeList()
            html.push('<ol>')
            list = 'ol'
          }
          html.push(`<li>${inlineMarkdown(ordered[1], vaultPaths)}</li>`)
          continue
        }
        if (/^\s*\|.*\|\s*$/u.test(line)) {
          closeList()
          const rows = []
          while (index < lines.length && /^\s*\|.*\|\s*$/u.test(lines[index])) {
            rows.push(lines[index].trim())
            index += 1
          }
          index -= 1
          const cells = (row) => row.replace(/^\||\|$/gu, '').split('|').map((cell) => cell.trim())
          const header = cells(rows[0])
          const hasDivider = rows.length > 1 && /^[\s:|-]+$/u.test(rows[1])
          const bodyRows = hasDivider ? rows.slice(2) : rows.slice(1)
          html.push('<table class="wm-table">')
          html.push(`<thead><tr>${header.map((cell) => `<th>${inlineMarkdown(cell, vaultPaths)}</th>`).join('')}</tr></thead>`)
          html.push('<tbody>')
          for (const row of bodyRows) html.push(`<tr>${cells(row).map((cell) => `<td>${inlineMarkdown(cell, vaultPaths)}</td>`).join('')}</tr>`)
          html.push('</tbody></table>')
          continue
        }
        closeList()
        html.push(`<p>${inlineMarkdown(line, vaultPaths)}</p>`)
      }
      closeList()
      if (code !== null) html.push(`<pre class="wm-pre"><code>${escapeHtml(code.join('\n'))}</code></pre>`)
      return html.join('\n')
    }

